CREATE TABLE billing_items (
    id INT PRIMARY KEY,
    item_description TEXT NOT NULL,
    unit_price NUMERIC(10,2) NOT NULL,
    quantity INTEGER NOT NULL,
    is_tax_exempt BOOLEAN NOT NULL DEFAULT FALSE
);
INSERT INTO billing_items VALUES (1, 'Cloud GPU Node', 149.99, 4, FALSE);
SELECT item_description, (unit_price * quantity) AS subtotal FROM billing_items;

CREATE TABLE event_logs (
    event_id INT PRIMARY KEY,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO event_logs (event_id, occurred_at) VALUES 
(1, '2026-09-24 14:00:00+00'),
(2, '2026-09-24 10:00:00-04');

-- Both timestamps represent the identical point in time
SELECT event_id, occurred_at AT TIME ZONE 'UTC' AS utc_time FROM event_logs;

CREATE TABLE accounts (
    id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    username TEXT NOT NULL
);
INSERT INTO accounts (username) VALUES ('alice'), ('bob');
SELECT id, username FROM accounts;

CREATE TABLE model_configs (
    id INT PRIMARY KEY,
    tags TEXT[] NOT NULL,
    parameters JSONB NOT NULL
);
INSERT INTO model_configs VALUES (
    1,
    ARRAY['llm', 'production'],
    '{"model": "gemini-2.5", "temperature": 0.7, "top_p": 0.95}'::JSONB
);

-- Extract JSONB value as text using ->> and check array containment
SELECT 
    parameters->>'model' AS model_name,
    tags @> ARRAY['llm'] AS has_llm_tag
FROM model_configs;
